package com.hallbooking.dao; import com.hallbooking.model.Hall;import com.hallbooking.util.DBConnection;import java.sql.*;import java.util.*;
public class HallDAO {private Hall map(ResultSet r)throws SQLException{Hall h=new Hall();h.setId(r.getInt("id"));h.setName(r.getString("name"));h.setLocation(r.getString("location"));h.setCapacity(r.getInt("capacity"));h.setPrice(r.getDouble("price"));h.setDescription(r.getString("description"));h.setStatus(r.getString("status"));return h;}public List<Hall> all()throws SQLException{List<Hall>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM halls WHERE status='AVAILABLE' ORDER BY id DESC");ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}return a;}public Hall byId(int id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM halls WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}}
